339	
340	  // SFCC-795 pass criterion 4: real DOM-order assertion via compareDocumentPosition, not just
341	  // "both nodes are present somewhere."
342	  test('message renders in DOM order between the stepper and the actions (secondaryActions)', () => {
343	    renderWithProviders(
344	      <ProductItem
345	        product={MOCK_LINE_ITEM}
346	        secondaryActions={<button type="button">Edit</button>}
347	        message={{ variant: 'error', text: 'This item is unavailable' }}
348	      />,
349	    );
350	
351	    const stepperNode = screen.getByRole('button', { name: INCREMENT_NAME });
352	    const messageNode = screen.getByTestId('zimm-inline-message');
353	    const actionsNode = screen.getByRole('button', { name: 'Edit' });
354	
355	    // messageNode follows stepperNode in document order.
356	    expect(stepperNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
357	    // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
358	    expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
359	  });
360	
361	  // SFCC-795 (plan step 3.3) pass criterion 2, first half: discountLabel omitted (every existing
362	  // caller today) renders no empty node.
363	  test('discountLabel omitted: no discount label node renders', () => {
364	    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);
