366	    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
367	  });
368	
369	  // SFCC-795 (plan step 3.3) pass criterion 2, second half + DOM order: with a discountLabel
370	  // prop, the label renders the exact copy, positioned beneath the stepper and ahead of the
371	  // (also present here) message — proving both slots coexist in the documented order rather than
372	  // just individually.
373	  test('discountLabel present: renders the exact copy, positioned beneath the stepper and ahead of the message', () => {
374	    renderWithProviders(
375	      <ProductItem
376	        product={MOCK_LINE_ITEM}
377	        discountLabel="20% off applied"
378	        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
379	      />,
380	    );
