511	      // Flush the mutation's own microtask queue (the Promise.resolve(...).then(...) inside
512	      // handleStepperQuantityChange) before asserting the negative — otherwise this would pass
513	      // trivially before the .then callback has even had a chance to run.
514	      await new Promise((resolve) => setTimeout(resolve, 0));
515	      expect(mockSetQuantity).not.toHaveBeenCalled();
516	    });
