/**
 * SFCC-270 (plan step 2.2). Covers this build's own pass criteria for product-item/index.tsx:
 * image renders with an alt, name renders uppercase, price renders, and the colour+size string
 * renders as one combined text node (not two separate ones).
 *
 * Mocks the smallest surface a rendered ProductItem calls transitively (testing.md's own
 * guidance), rather than standing up the full commerce-hook dependency chain a real render
 * would need (CurrencyContext, CommerceApiProvider, useVariant/useVariationParams/
 * useSelectedStore via the real useDerivedProduct, react-intl's IntlProvider via useIntl) —
 * this test is about ProductItem's OWN render contract, not re-proving those hooks' own
 * correctness, which is out of this file's scope. `use-multi-site` is mocked for the same
 * parse-failure-under-Vitest reason item-variant/index.test.tsx's own docblock explains.
 *
 * SFCC-795 (plan step 3.2) extends this file with the `message` prop's own pass criteria: DOM
 * order (message between the stepper and the actions) and the `hasError` wiring into
 * `ZimmCartItem`'s recipe. The gap VALUE itself (12px vs 16px token) is proven directly against
 * the exported recipe in product-item.css.test.ts, not here — this file's own `HideOnMobile`/
 * `HideOnDesktop` both render simultaneously under jsdom (see the existing price-node comment
 * below), which is the same underlying fact (jsdom does not evaluate CSS `@media` rules the way
 * a real browser does) that makes a `getComputedStyle`/`toHaveStyle` assertion on a
 * media-query-scoped `gap` value unreliable here — so the wiring is proven instead via a
 * call-args spy on `useMultiStyleConfig` (still the REAL Chakra implementation underneath,
 * `shared/ui/useMultiStyleConfig` is a bare re-export of it — confirmed by reading that file —
 * so nothing about ProductItem's actual rendering changes; only its call args are observed).
 *
 * SFCC-795 (plan step 3.3) extends this file with the `discountLabel` prop's own pass criteria:
 * omitted renders no node, present renders the exact copy positioned beneath the stepper and
 * ahead of `message` (DOM order proven the same compareDocumentPosition way as the message-vs-
 * actions test above). The was/now promotional-price mechanism this step also covers is NOT
 * tested in this file — it isn't ProductItem's own contract, it's item-price.tsx's (via base
 * `display-price`) — see item-variant/index.test.tsx's own new coverage for that, including a
 * disclosed limitation on which of item-price.tsx's two branches can actually reach it.
 */
import React from 'react';
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { ChakraProvider } from '@chakra-ui/react';
import { IntlProvider } from 'react-intl';
import { MemoryRouter } from 'react-router-dom';
import theme from 'app/theme';
import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
import { useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
import ProductItem from '.';

vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
  default: vi.fn(),
}));

// SFCC-795: wraps the REAL useMultiStyleConfig (a bare re-export of @chakra-ui/react's own hook —
// confirmed in node_modules/@salesforce/retail-react-app/.../shared/ui/useMultiStyleConfig) in a
// vi.fn so its call args are inspectable, without changing what it actually returns/does. Lets
// the `hasError` wiring test below prove the exact props ProductItem passes through, rather than
// asserting a media-query-scoped computed style value jsdom does not reliably resolve (see this
// file's own docblock).
vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>();
  return {
    ...actual,
    useMultiStyleConfig: vi.fn(actual.useMultiStyleConfig),
  };
});

// SFCC-271-250 (plan step 3.5): useDerivedProduct is now a controllable vi.fn() (was a static
// inline factory returning a fixed quantity) so individual tests can drive ZimmQuantityStepper's
// min/max/disabled boundaries at a specific quantity — the same vi.mocked(...) pattern already
// used below for useMultiSite/useMultiStyleConfig. Default return value is set in beforeEach.
vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
  useDerivedProduct: vi.fn(),
}));

vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
  useCurrentBasket: () => ({ data: undefined }),
}));

// item-attributes.tsx imports PromoPopover unconditionally, which imports the base SFCC icons
// barrel — that barrel has a top-level side effect (`AmexSymbol.viewBox = ...`) that throws
// under Vitest (SVG imports resolve to raw path strings here, not components). Same root cause,
// same fix shape, as testing.md's documented ZimmIcon workaround, just via a different import
// path (PromoPopover, not ZimmIcon) — not fixable from this test file beyond mocking it away.
vi.mock('@salesforce/retail-react-app/app/components/promo-popover', () => ({
  default: ({ children }: { children?: React.ReactNode }) => <>{children}</>,
}));

// SFCC-795 rework (Marcel's own visual checkpoint against the real Figma file): ZimmInlineMessage's
// `warning` variant now renders a real ZimmIcon, which hits the same top-level-side-effect gap as
// the promo-popover mock above (testing.md's documented "Known gap: ZimmIcon throws under
// Vitest"). This file's own "message with variant=\"warning\"" test below renders ProductItem with
// a warning message, which now reaches that real (unmocked) icon render for the first time — mocked
// at the same smallest surface as footerNavColumn/index.test.tsx / zimmSubscribeSection/index.test.tsx.
// Nothing this file asserts on depends on the icon's own content.
vi.mock('app/components/ui-kits/atoms/zimmIcon', () => ({
  ZimmIcon: (props: { type: string }) => <div data-testid="mock-info-icon" data-type={props.type} />,
}));

vi.mock('@salesforce/commerce-sdk-react', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/commerce-sdk-react')>();
  return {
    ...actual,
    usePromotions: () => ({ data: undefined }),
    useProducts: () => ({ data: undefined, isLoading: false }),
    useProduct: () => ({ data: undefined, isLoading: false }),
  };
});

// Bypasses the real utility's own variationAttributes/variationValues matching logic — this
// test is about ProductItem's own render contract (does a combined value render as one node),
// not about re-proving getDisplayVariationValues' own correctness. See
// item-variant/item-attributes.tsx's own SFCC-270 docblock for combineAttributeValues' contract.
vi.mock('@salesforce/retail-react-app/app/utils/product-utils', async (importOriginal) => {
  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/utils/product-utils')>();
  return {
    ...actual,
    getDisplayVariationValues: () => ({ Colour: 'Lilac Sand', Size: 'One size' }),
  };
});

const mockUseMultiSite = vi.mocked(useMultiSite);
const mockUseMultiStyleConfig = vi.mocked(useMultiStyleConfig);
const mockUseDerivedProduct = vi.mocked(useDerivedProduct);
const mockSetQuantity = vi.fn();

// SFCC-271-250: ZimmQuantityStepper's own accessible names (zimmQuantityStepper/index.tsx's
// react-intl defaultMessages) — used throughout this file in place of the old, now-removed
// ProductQuantityPicker's "Quantity:" label text/input, neither of which renders in this tree
// any more.
const DECREMENT_NAME = 'Decrease quantity';
const INCREMENT_NAME = 'Increase quantity';

// ChakraProvider with this project's own theme is required, not optional here — without it,
// `textStyle="productNames"`/`"price"`/`"caption"` resolve against Chakra's default (empty)
// textStyles, and item-price.tsx's `useBreakpointValue` throws outright reading
// `theme.breakpoints` off an undefined theme. Same setup zimmButton's own test uses.
const renderWithProviders = (ui: React.ReactElement) =>
  render(
    <ChakraProvider theme={theme}>
      <MemoryRouter>
        <IntlProvider locale="en-AU" defaultLocale="en-AU">
          {ui}
        </IntlProvider>
      </MemoryRouter>
    </ChakraProvider>,
  );

const MOCK_LINE_ITEM = {
  itemId: 'a1b2c3d4e5f6a1b2c3d4e5f6',
  productId: '25595021M',
  id: '25595021M',
  productName: 'Lilac Sand Silk Midi Dress',
  name: 'Lilac Sand Silk Midi Dress',
  price: 495,
  priceAfterItemDiscount: 495,
  pricePerUnit: 495,
  quantity: 1,
  imageGroups: [
    {
      viewType: 'small',
      images: [{ alt: 'Lilac Sand Silk Midi Dress', link: 'https://example.invalid/lilac-sand.jpg' }],
    },
  ],
};

describe('ProductItem', () => {
  // jsdom has no matchMedia implementation, and item-price.tsx's `isDesktop` uses
  // useBreakpointValue internally, which calls it — a per-file polyfill, not a change to the
  // frozen vitest.setup.ts (Tier 1). Same pattern and reasoning as drawer-menu/index.test.tsx's
  // own beforeEach.
  beforeEach(() => {
    Object.defineProperty(window, 'matchMedia', {
      writable: true,
      value: vi.fn().mockImplementation((query: string) => ({
        matches: false,
        media: query,
        onchange: null,
        addListener: vi.fn(),
        removeListener: vi.fn(),
        addEventListener: vi.fn(),
        removeEventListener: vi.fn(),
        dispatchEvent: vi.fn(),
      })),
    });

    mockUseMultiSite.mockReturnValue({
      site: { id: 'ZimmermannAU' },
      buildUrl: (path: string) => path,
    });

    // SFCC-795: fresh call history per test — mockUseMultiStyleConfig still delegates to the
    // real implementation (see the top-of-file vi.mock), this only clears recorded .mock.calls.
    mockUseMultiStyleConfig.mockClear();

    // SFCC-271-250: default quantity=1 matches every pre-existing test's own assumption (min
    // boundary, decrement disabled) — the stepper-boundary and mutation tests further below
    // override this per-test with their own mockReturnValue.
    mockSetQuantity.mockClear();
    mockUseDerivedProduct.mockReturnValue({
      stepQuantity: 1,
      showInventoryMessage: false,
      inventoryMessage: '',
      quantity: 1,
      setQuantity: mockSetQuantity,
    });
  });

  test('renders the image with an alt, the name uppercase, the price, and one combined colour+size node', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    // Image renders with an alt.
    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();

    // Name renders uppercase (textStyle="productNames" sets text-transform, not literal casing —
    // the DOM text content itself stays as authored). Asserted on the <Heading> textStyle is
    // actually applied to, not the nested <Link> — see item-variant/index.test.tsx's own note
    // on why (text-transform is CSS-inherited, and jsdom's getComputedStyle does not reliably
    // resolve inherited declarations).
    expect(screen.getByRole('heading', { level: 2 })).toHaveStyle({ textTransform: 'uppercase' });

    // Price renders — DisplayPrice/CurrentPrice formats $495.00 via react-intl; rendered twice
    // (mobile + desktop slots both exist in the DOM under jsdom, which does not evaluate CSS
    // media queries — see header/rightBar/index.test.tsx's own note on this exact behaviour).
    expect(screen.getAllByText('$495.00').length).toBeGreaterThan(0);

    // The colour+size string renders as ONE text node containing both values — not two
    // separate nodes. An exact-string query only matches if both values live in the same node.
    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
  });

  // Round 2 rework, must-fix 4: the gift-card capability slot. Only the capability is asserted
  // here — not real gift-card detection, which this build still cannot do (see this component's
  // own docblock).
  test('hideStepperAndActions suppresses the stepper and every actions surface, and nothing throws', () => {
    expect(() =>
      renderWithProviders(
        <ProductItem
          product={MOCK_LINE_ITEM}
          primaryAction={<button type="button">Remove</button>}
          secondaryActions={<button type="button">Edit</button>}
          deliveryActions={<span>Ship to store</span>}
          hideStepperAndActions
        />,
      ),
    ).not.toThrow();

    // Stepper: SFCC-271-250 swapped ProductQuantityPicker for ZimmQuantityStepper — the absence
    // of both its accessible button names proves the stepper itself did not render.
    expect(screen.queryByRole('button', { name: DECREMENT_NAME })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: INCREMENT_NAME })).not.toBeInTheDocument();

    // Actions: primaryAction/secondaryActions/deliveryActions all suppressed.
    expect(screen.queryByRole('button', { name: 'Remove' })).not.toBeInTheDocument();
    expect(screen.queryByRole('button', { name: 'Edit' })).not.toBeInTheDocument();
    expect(screen.queryByText('Ship to store')).not.toBeInTheDocument();

    // The rest of the component is unaffected — image/name/price/attributes still render.
    expect(screen.getByAltText('Lilac Sand Silk Midi Dress')).toBeInTheDocument();
    expect(screen.getByText('Lilac Sand, One size')).toBeInTheDocument();
  });

  test('every existing caller (hideStepperAndActions omitted) is unaffected — the stepper and actions still render', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        primaryAction={<button type="button">Remove</button>}
        secondaryActions={<button type="button">Edit</button>}
        deliveryActions={<span>Ship to store</span>}
      />,
    );

    expect(screen.getByRole('button', { name: INCREMENT_NAME })).toBeInTheDocument();
    expect(screen.getByRole('button', { name: DECREMENT_NAME })).toBeInTheDocument();
    expect(screen.getAllByRole('button', { name: 'Remove' }).length).toBeGreaterThan(0);
    expect(screen.getByRole('button', { name: 'Edit' })).toBeInTheDocument();
    expect(screen.getAllByText('Ship to store').length).toBeGreaterThan(0);
  });

  // CodeRabbit (SFCC-11 cumulative review, originally against product-quantity-picker.tsx's own
  // handleQuantityChange): the old default, `noop`, returned undefined synchronously -
  // `undefined.then` threw before the old handler even finished. SFCC-271-250 (plan step 3.5)
  // replaced that picker's render branch with ZimmQuantityStepper and
  // handleStepperQuantityChange (product-item/index.tsx), which keeps the identical shape
  // (`Promise.resolve(onItemQuantityChange(...)).then(...)`) — this test still proves a caller
  // that omits the prop entirely can actually change the quantity without throwing.
  //
  // A plain fireEvent.click on the increment button is sufficient here: unlike the old
  // NumberInput-based picker, ZimmQuantityStepper's controls are real ZimmButtons wired directly
  // to onClick (confirmed against zimmQuantityStepper/index.test.tsx's own click-based tests,
  // which already pass this way) — the old ArrowUp-keydown workaround was specific to Chakra's
  // NumberInput internals and no longer applies to this component.
  test('omitting onItemQuantityChange and actually changing quantity does not throw', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    expect(() => {
      fireEvent.click(screen.getByRole('button', { name: INCREMENT_NAME }));
    }).not.toThrow();
  });

  // SFCC-795 pass criterion 7: `message` omitted (every existing caller today) renders nothing,
  // and ZimmCartItem resolves `hasError` to false. product-item.css.test.ts proves separately,
  // at the recipe level, that hasError:false keeps the Item Details gap at its existing 12px
  // desktop token — this test proves the WIRING that gets it there (see this file's own
