    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
  });

  test('message with variant="warning": renders the message, but ZimmCartItem still resolves hasError=false', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
      />,
    );

    expect(screen.getByText('Maximum purchase quantity reached for this size')).toBeInTheDocument();

    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: false });
  });

  test('message with variant="error": renders the message, and ZimmCartItem resolves hasError=true', () => {
    renderWithProviders(
      <ProductItem product={MOCK_LINE_ITEM} message={{ variant: 'error', text: 'This item is unavailable' }} />,
    );

    expect(screen.getByText('This item is unavailable')).toBeInTheDocument();

    const cartItemCalls = mockUseMultiStyleConfig.mock.calls.filter((call: unknown[]) => call[0] === 'ZimmCartItem');
    expect(cartItemCalls).toHaveLength(1);
    expect(cartItemCalls[0][1]).toEqual({ hasError: true });
  });

  // SFCC-795 pass criterion 4: real DOM-order assertion via compareDocumentPosition, not just
  // "both nodes are present somewhere."
  test('message renders in DOM order between the stepper and the actions (secondaryActions)', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        secondaryActions={<button type="button">Edit</button>}
        message={{ variant: 'error', text: 'This item is unavailable' }}
      />,
    );

    const stepperNode = screen.getByRole('button', { name: INCREMENT_NAME });
    const messageNode = screen.getByTestId('zimm-inline-message');
    const actionsNode = screen.getByRole('button', { name: 'Edit' });

    // messageNode follows stepperNode in document order.
    expect(stepperNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    // actionsNode follows messageNode in document order — i.e. the message precedes the actions row.
    expect(messageNode.compareDocumentPosition(actionsNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  });

  // SFCC-795 (plan step 3.3) pass criterion 2, first half: discountLabel omitted (every existing
  // caller today) renders no empty node.
  test('discountLabel omitted: no discount label node renders', () => {
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    expect(screen.queryByTestId('zimm-discount-label')).not.toBeInTheDocument();
  });

  // SFCC-795 (plan step 3.3) pass criterion 2, second half + DOM order: with a discountLabel
  // prop, the label renders the exact copy, positioned beneath the stepper and ahead of the
  // (also present here) message — proving both slots coexist in the documented order rather than
  // just individually.
  test('discountLabel present: renders the exact copy, positioned beneath the stepper and ahead of the message', () => {
    renderWithProviders(
      <ProductItem
        product={MOCK_LINE_ITEM}
        discountLabel="20% off applied"
        message={{ variant: 'warning', text: 'Maximum purchase quantity reached for this size' }}
      />,
    );

    const discountNode = screen.getByTestId('zimm-discount-label');
    expect(discountNode).toHaveTextContent('20% off applied');

    const stepperNode = screen.getByRole('button', { name: INCREMENT_NAME });
    const messageNode = screen.getByTestId('zimm-inline-message');

    // discountNode follows stepperNode in document order.
    expect(stepperNode.compareDocumentPosition(discountNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
    // messageNode follows discountNode in document order — i.e. the discount label precedes the message.
    expect(discountNode.compareDocumentPosition(messageNode) & Node.DOCUMENT_POSITION_FOLLOWING).toBeTruthy();
  });

  // SFCC-271-250 (plan step 3.5) pass criterion 1: with c_maxOrderQuantity absent, the stepper's
  // effective max resolves to getMaxOrderQuantity's own fallback of 3 — proven against the real,
  // rendered ZimmQuantityStepper's own disabled boundary, not by spying on the util's call args.
  test('c_maxOrderQuantity absent: stepper max resolves to the fallback of 3 (increment disabled at quantity 3)', () => {
    mockUseDerivedProduct.mockReturnValue({
      stepQuantity: 1,
      showInventoryMessage: false,
      inventoryMessage: '',
      quantity: 3,
      setQuantity: mockSetQuantity,
    });
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    const increment = screen.getByRole('button', { name: INCREMENT_NAME });
    expect(increment).toHaveAttribute('aria-disabled', 'true');

    fireEvent.click(increment);
    expect(mockSetQuantity).not.toHaveBeenCalled();
    expect(screen.getByText('3')).toBeInTheDocument();
  });

  // Converse of the above: one below the fallback cap, increment must still be live — proves the
  // disabled state above is actually the cap kicking in, not the control being always-disabled.
  test('c_maxOrderQuantity absent: increment is still enabled below the fallback cap (quantity 2)', () => {
    mockUseDerivedProduct.mockReturnValue({
      stepQuantity: 1,
      showInventoryMessage: false,
      inventoryMessage: '',
      quantity: 2,
      setQuantity: mockSetQuantity,
    });
    renderWithProviders(<ProductItem product={MOCK_LINE_ITEM} />);

    expect(screen.getByRole('button', { name: INCREMENT_NAME })).not.toHaveAttribute('aria-disabled', 'true');
  });

  // SFCC-271-250 pass criterion 2: a real c_maxOrderQuantity on the product overrides
  // getMaxOrderQuantity's fallback — allows incrementing up to 5 (enabled below it) and no
  // further (disabled, and inert on click, at it).
  test('c_maxOrderQuantity: 5 on the product: increment enabled below 5, disabled and inert at 5', () => {
    const productWithCap = { ...MOCK_LINE_ITEM, c_maxOrderQuantity: 5 };

    mockUseDerivedProduct.mockReturnValue({
      stepQuantity: 1,
      showInventoryMessage: false,
      inventoryMessage: '',
