import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';

const messages = defineMessages({
  decrement: { id: 'zimm_quantity_stepper.decrement', defaultMessage: 'Decrease quantity' },
  increment: { id: 'zimm_quantity_stepper.increment', defaultMessage: 'Increase quantity' },
});

/** Cart-line minimum meaningful quantity. 0 would mean "remove the line", a separate action this
 *  molecule does not own — see ZimmQuantityStepperProps.min. */
const MIN_DEFAULT = 1;

export type ZimmQuantityStepperProps = {
  /** Current quantity rendered between the two buttons. */
  quantity: number;
  /** Lower bound (inclusive) — decrement disables at this value. Defaults to 1. */
  min?: number;
  /**
   * Upper bound (inclusive) — increment disables at this value. Always required: the caller
   * (inventory ATS, or a hardcoded per-SKU cap — see project memory on max order quantity) is the
   * one that knows the real ceiling. This molecule never computes or guesses one.
   */
  max: number;
  /**
   * Fully out-of-stock / unavailable for this line — forces BOTH buttons inert regardless of
   * where `quantity` sits between `min`/`max`, and dims the value display to match. This molecule
   * does not derive availability itself (no inventory lookups here) — the caller passes the
   * already-resolved flag.
   */
  isUnavailable?: boolean;
  /** Called with the computed next quantity (`quantity - 1`) when decrement is pressed while
   *  active. Never called while the decrement button is inert. */
  onDecrement: (nextQuantity: number) => void;
  /** Called with the computed next quantity (`quantity + 1`) when increment is pressed while
   *  active. Never called while the increment button is inert. */
  onIncrement: (nextQuantity: number) => void;
};

/**
 * Molecule — cart-line quantity stepper (SFCC-271). Composes two `ZimmButton variant="icon"`
 * controls (hover/press/focus/disabled states are entirely zimmButton.css.ts's own, unchanged
 * here) around a numeric value display, styled by the co-located zimmQuantityStepper.css.ts.
 *
 * Controlled, not stateful: this component never mutates `quantity` itself, it only reports the
 * caller's next intended value via `onDecrement`/`onIncrement` — the actual basket update (an
 * SFCC SDK call) belongs to whichever container wires this in, per
 * .claude/rules/components.md's container/presentational separation. That wiring is a later
 * commit in this same build and has not happened yet.
 *
 * `ariaDisabled` (not `disabled`) is used for every inert state here, matching ZimmButton's own
 * documented guidance for an "unavailable but explainable" control: the button stays reachable
 * and announced by assistive tech (its dimmed appearance and the adjacent value are the
 * explanation) rather than disappearing from the tab order the way a native `disabled` attribute
 * would. `onClick` is additionally guarded inside this component (not just left to ZimmButton's
 * own ariaDisabled suppression) so the "clicking does nothing" contract holds even if that
 * changed.
 *
 * @param props see ZimmQuantityStepperProps
 */
export const ZimmQuantityStepper = ({
  quantity,
  min = MIN_DEFAULT,
  max,
  isUnavailable = false,
  onDecrement,
  onIncrement,
}: ZimmQuantityStepperProps) => {
  const intl = useIntl();
  const styles = useMultiStyleConfig('ZimmQuantityStepper', { disabled: isUnavailable });

  const decrementInert = isUnavailable || quantity <= min;
  const incrementInert = isUnavailable || quantity >= max;

  const handleDecrement = () => {
    if (decrementInert) return;
    onDecrement(quantity - 1);
  };

  const handleIncrement = () => {
    if (incrementInert) return;
    onIncrement(quantity + 1);
  };

  return (
    <chakra.div __css={styles.root}>
      <ZimmButton
        variant="icon"
        icon="minus"
        label={intl.formatMessage(messages.decrement)}
        ariaDisabled={decrementInert}
        onClick={handleDecrement}
      />
      {/* aria-live: a shopper-caused change to their own just-clicked control still benefits
          screen reader users exploring the surrounding value, not just the button they pressed. */}
      <chakra.span __css={styles.value} aria-live="polite">
        {quantity}
      </chakra.span>
      <ZimmButton
        variant="icon"
        icon="plus"
        label={intl.formatMessage(messages.increment)}
        ariaDisabled={incrementInert}
        onClick={handleIncrement}
      />
    </chakra.div>
  );
};

